// Bad example: String concatenation (creates garbage)
String bad = "";
for (int i = 0; i < 3; i++) {
    bad = bad + i;
}

// Good example: StringBuilder (reuses object)
StringBuilder good = new StringBuilder();
for (int i = 0; i < 3; i++) {
    good.append(i);
}
String result = good.toString();
